import random
import struct
from typing import List, Tuple

# This generator targets PFFFT fuzzers expecting FUZZ_PARAM_STR to provide
# raw binary float buffers. We craft valid float arrays of sizes that are
# typical for PFFFT: N must be (2^a)*(3^b)*(5^c) with a >= 5. The fuzzers
# will size their buffers from setup (N and transform type). Our blob will be
# memcpy'ed into those buffers and zero-padded if shorter, so we keep the blob
# length equal to a plausible size in bytes to produce fully initialized data.
#
# Strategy
# - Produce time-domain buffers of floats that are numerically well-behaved,
#   covering various patterns: impulses, sinusoids with harmonic sums, ramps,
#   noise, DC offsets, windowed tones, and denormal/NaN/Inf sprinkling.
# - Support both real (N floats) and complex (2*N floats) by sometimes emitting
#   interleaved real/imag pairs.
# - Choose N from valid PFFFT sizes up to a reasonable cap, focusing on common
#   powers: 32, 48, 64, 80, 96, 128, 144, 160, 192, 256, 320, 384, 480, 512,
#   640, 768, 960, 1024. Keep total bytes <= 4096.
# - Produce length that fits within 4096; prefer exactly matching a chosen N
#   to eliminate zero padding most of the time.
# - Deterministic randomness via seed.

MAX_BYTES = 4096

# Valid sizes N satisfying a >= 5 in 2^a * 3^b * 5^c, and keeping within limit
# for complex case (2*N floats => 8*N bytes <= 4096 -> N <= 512).
# For real case (4*N bytes <= 4096 -> N <= 1024).
VALID_SIZES = [
    32, 48, 64, 80, 96, 128, 144, 160, 192, 256, 288, 320, 384, 400, 432,
    480, 512, 576, 640, 720, 768, 800, 864, 960, 1024
]

# Patterns for generating content

def _linspace(n: int, start: float, stop: float) -> List[float]:
    if n <= 1:
        return [start]
    step = (stop - start) / (n - 1)
    return [start + i * step for i in range(n)]


def _sine_wave(n: int, freq: float, phase: float = 0.0, amp: float = 1.0) -> List[float]:
    # freq in cycles over N samples
    twopi = 6.283185307179586
    return [amp * (0.5 * (random.random() * 0 + 2) * 0 + 1) *  # keep deterministic shape
            (0.0 + __import__('math').sin((twopi * freq * i / n) + phase)) for i in range(n)]


def _multi_tone(n: int, tones: List[Tuple[float, float]]) -> List[float]:
    # tones: list of (freq, amp)
    import math
    out = [0.0] * n
    for f, a in tones:
        for i in range(n):
            out[i] += a * math.sin(2 * math.pi * f * i / n)
    # normalize to avoid clipping
    maxabs = max(1e-12, max(abs(x) for x in out))
    scale = 0.9 / maxabs
    return [x * scale for x in out]


def _impulse(n: int, pos: int, amp: float = 1.0) -> List[float]:
    out = [0.0] * n
    if 0 <= pos < n:
        out[pos] = amp
    return out


def _ramp(n: int, start: float = -1.0, stop: float = 1.0) -> List[float]:
    return _linspace(n, start, stop)


def _noise(n: int, amp: float = 0.5) -> List[float]:
    return [amp * (random.random() * 2.0 - 1.0) for _ in range(n)]


def _windowed_tone(n: int, freq: float) -> List[float]:
    import math
    # Hann window
    out = []
    for i in range(n):
        w = 0.5 - 0.5 * math.cos(2 * math.pi * i / (n - 1 if n > 1 else 1))
        out.append(w * math.sin(2 * math.pi * freq * i / n))
    return out


def _sprinkle_specials(arr: List[float], probability: float = 0.02) -> None:
    # Insert occasional NaN/Inf/denormals to exercise code paths. Still valid IEEE-754.
    import math
    for i in range(len(arr)):
        r = random.random()
        if r < probability:
            choice = random.randint(0, 4)
            if choice == 0:
                arr[i] = float('nan')
            elif choice == 1:
                arr[i] = float('inf')
            elif choice == 2:
                arr[i] = -float('inf')
            elif choice == 3:
                # denormal-ish tiny number
                arr[i] = 1e-40 * (1 if random.random() < 0.5 else -1)
            else:
                arr[i] = 0.0


def _pack_floats(values: List[float]) -> bytes:
    return struct.pack('<' + 'f' * len(values), *values)


def _gen_real(n: int) -> List[float]:
    mode = random.randint(0, 7)
    if mode == 0:
        arr = _sine_wave(n, freq=random.choice([1, 2, 3, 5, 7, n // 8 or 1]), phase=random.random() * 6.28318, amp=1.0)
    elif mode == 1:
        tones = []
        k = random.randint(2, 5)
        for _ in range(k):
            tones.append((random.randint(1, max(1, n // 4)), random.uniform(0.2, 1.0)))
        arr = _multi_tone(n, tones)
    elif mode == 2:
        arr = _impulse(n, pos=random.randrange(n), amp=random.uniform(0.5, 2.0))
    elif mode == 3:
        arr = _ramp(n, start=random.uniform(-2, 0), stop=random.uniform(0, 2))
    elif mode == 4:
        arr = _noise(n, amp=random.uniform(0.1, 1.0))
    elif mode == 5:
        arr = [random.choice([0.0, 1.0, -1.0]) for _ in range(n)]
    elif mode == 6:
        arr = _windowed_tone(n, freq=random.randint(1, max(1, n // 6)))
    else:
        # DC offset +/-
        dc = random.uniform(-1.5, 1.5)
        arr = [dc for _ in range(n)]
    _sprinkle_specials(arr, probability=0.01)
    return arr


def _gen_complex(n: int) -> List[float]:
    # Interleaved real/imag pairs, length 2*n floats
    real = _gen_real(n)
    imag_mode = random.randint(0, 3)
    if imag_mode == 0:
        imag = [0.0] * n
    elif imag_mode == 1:
        imag = _noise(n, amp=random.uniform(0.05, 0.7))
    elif imag_mode == 2:
        imag = _sine_wave(n, freq=random.randint(1, max(1, n // 5)), phase=random.random() * 6.28318, amp=0.7)
    else:
        imag = _ramp(n, start=-0.5, stop=0.5)
    _sprinkle_specials(imag, probability=0.01)
    interleaved = []
    for r, im in zip(real, imag):
        interleaved.append(r)
        interleaved.append(im)
    return interleaved


def _choose_size(is_complex: bool) -> int:
    # Respect overall byte cap
    candidates = []
    for n in VALID_SIZES:
        bytes_needed = (2 * n if is_complex else n) * 4
        if bytes_needed <= MAX_BYTES:
            candidates.append(n)
    return random.choice(candidates)


def generate(seed: int) -> bytes:
    random.seed(seed)
    # Randomly choose to target real or complex; both are valid raw float buffers.
    is_complex = bool(random.getrandbits(1))
    n = _choose_size(is_complex)

    if is_complex:
        values = _gen_complex(n)
    else:
        values = _gen_real(n)

    blob = _pack_floats(values)

    # Occasionally prepend a tiny header-like marker that is still valid bytes for floats.
    # This can create distinct patterns when memcpy'ed into larger buffers, but remains
    # valid raw data. Keep infrequent and small.
    if random.random() < 0.15:
        marker = struct.pack('<I', 0xdeadbeef)
        # ensure we don't exceed MAX_BYTES
        max_extra = MAX_BYTES - len(blob)
        if len(marker) <= max_extra:
            blob = marker + blob

    # Ensure size within cap
    if len(blob) > MAX_BYTES:
        blob = blob[:MAX_BYTES]
    return blob
